<?php require_once __DIR__.'/../includes/functions.php'; require_once __DIR__.'/../includes/csrf.php';
$inviteToken=trim($_GET['invite']??'');$publicToken=trim($_GET['token']??'');$survey=null;if($inviteToken){$s=db()->prepare("SELECT s.*,i.completed_at FROM survey_invitations i JOIN surveys s ON s.id=i.survey_id WHERE i.invite_token=?");$s->execute([$inviteToken]);$survey=$s->fetch();}elseif($publicToken){$s=db()->prepare('SELECT * FROM surveys WHERE public_token=?');$s->execute([$publicToken]);$survey=$s->fetch();}if(!$survey){http_response_code(404);$error='Survey not found.';}elseif($survey['status']!=='active'){$error='This survey is not currently active.';}elseif(!empty($survey['completed_at'])){$error='This invitation has already been used.';}elseif($survey['starts_at']&&strtotime($survey['starts_at'])>time()){$error='This survey has not opened yet.';}elseif($survey['ends_at']&&strtotime($survey['ends_at'])<time()){$error='This survey is closed.';}else{$q=db()->prepare('SELECT * FROM survey_questions WHERE survey_id=? ORDER BY sort_order,id');$q->execute([$survey['id']]);$questions=$q->fetchAll();foreach($questions as &$question){$o=db()->prepare('SELECT * FROM question_options WHERE question_id=? ORDER BY sort_order,id');$o->execute([$question['id']]);$question['options']=$o->fetchAll();}unset($question);}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="<?=e(csrf_token())?>"><title><?=isset($survey)?e($survey['title']):'Survey'?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="assets/css/style.css"></head><body><div class="survey-shell px-3"><a class="text-decoration-none fw-bold fs-4 text-dark" href="index.php">Pulse<span class="text-primary">Point</span></a><div id="surveyCard" class="panel bg-white p-4 p-md-5 mt-3"><?php if(isset($error)):?><div class="text-center py-5"><h2><?=e($error)?></h2><a href="index.php" class="btn btn-primary mt-3">Return home</a></div><?php else:?><div class="mb-4"><span class="badge badge-soft rounded-pill mb-2">Employee Survey</span><h1 class="fw-bold"><?=e($survey['title'])?></h1><p class="text-secondary"><?=nl2br(e($survey['description']))?></p><?php if($survey['anonymous']):?><div class="small text-success">● This survey is configured for anonymous responses.</div><?php endif;?></div><form id="surveyForm"><input type="hidden" id="survey_token" value="<?=e($survey['public_token'])?>"><input type="hidden" id="invitation_token" value="<?=e($inviteToken)?>"><?php foreach($questions as $i=>$question):?><div class="question-block mb-4" data-question="<?=$question['id']?>" data-type="<?=e($question['question_type'])?>"><label class="form-label fw-semibold d-block"><?=($i+1)?>. <?=e($question['question_text'])?><?=$question['required']?' <span class="text-danger">*</span>':''?></label><?php if(in_array($question['question_type'],['single','multiple'])):?><?php foreach($question['options'] as $opt):?><div class="form-check mb-2"><input class="form-check-input" name="q<?=$question['id']?><?=$question['question_type']==='multiple'?'[]':''?>" value="<?=$opt['id']?>" type="<?=$question['question_type']==='single'?'radio':'checkbox'?>"><label class="form-check-label"><?=e($opt['option_text'])?></label></div><?php endforeach;?><?php elseif($question['question_type']==='dropdown'):?><select class="form-select"><option value="">Select an option…</option><?php foreach($question['options'] as $opt):?><option value="<?=$opt['id']?>"><?=e($opt['option_text'])?></option><?php endforeach;?></select><?php elseif($question['question_type']==='rating'):?><div class="rating-group btn-group" role="group"><?php for($n=1;$n<=5;$n++):?><input type="radio" class="btn-check" name="q<?=$question['id']?>" value="<?=$n?>" id="q<?=$question['id']?>r<?=$n?>"><label class="btn btn-outline-primary" for="q<?=$question['id']?>r<?=$n?>"><?=$n?></label><?php endfor;?></div><?php elseif($question['question_type']==='yesno'):?><div class="btn-group"><input type="radio" class="btn-check" name="q<?=$question['id']?>" value="Yes" id="q<?=$question['id']?>yes"><label class="btn btn-outline-primary" for="q<?=$question['id']?>yes">Yes</label><input type="radio" class="btn-check" name="q<?=$question['id']?>" value="No" id="q<?=$question['id']?>no"><label class="btn btn-outline-primary" for="q<?=$question['id']?>no">No</label></div><?php elseif($question['question_type']==='long_text'):?><textarea class="form-control" rows="4" placeholder="Type your answer…"></textarea><?php else:?><input type="text" class="form-control" placeholder="Type your answer…"><?php endif;?></div><?php endforeach;?><button class="btn btn-primary btn-lg w-100" type="submit">Submit response</button></form><?php endif;?></div></div><script src="https://code.jquery.com/jquery-3.7.1.min.js"></script><script src="assets/js/app.js"></script><script src="assets/js/survey.js"></script></body></html>